using System.Globalization;

namespace Editrainer;

/// <summary>
/// The app's own texts. Each is written in Spanish in the code, and that text is its key here.
/// Names of Pokémon, moves, abilities and items come from PKHeX in the language chosen.
/// </summary>
public static class Strings
{
    public sealed record Language(string Code, string Name, string GameData)
    {
        public override string ToString() => Name;
    }

    // PKHeX has no game data in Portuguese, Russian, Hindi or Arabic: those fall back to English names.
    public static readonly Language[] Languages =
    [
        new("es", "Español", "es"), new("en", "English", "en"), new("zh", "简体中文", "zh-Hans"), new("fr", "Français", "fr"),
    ];

    public static Language Current { get; private set; } = Languages[0];

    public static void Use(string code) => Current = Languages.FirstOrDefault(l => l.Code == code) ?? Languages[0];

    public static string T(string spanish) => Current.Code switch {
        "en" when Table.TryGetValue(spanish, out var row) => row.En,
        "zh" when Table.TryGetValue(spanish, out var row) => row.Zh,
        "fr" when Table.TryGetValue(spanish, out var row) => row.Fr,
        _ => spanish,
    };

    public static string T(string spanish, params object?[] values) => string.Format(CultureInfo.CurrentCulture, T(spanish), values);

    /// <summary>For the tests: every text, as Spanish, English, Chinese and French.</summary>
    public static IEnumerable<string[]> AllTexts => Table.Select(row => new[] { row.Key, row.Value.En, row.Value.Zh, row.Value.Fr });
    public static bool Has(string spanish) => Table.ContainsKey(spanish);

