        // Validation
        ["Cada {0} debe estar entre 0 y {1}."] = ("Each {0} must be between 0 and {1}.", "每项{0}必须在 0 到 {1} 之间。", "Chaque {0} doit être entre 0 et {1}."),
        ["{0}: los EV suman {1}. El máximo es {2}."] = ("{0}: EVs add up to {1}. The maximum is {2}.", "{0}：努力值合计 {1}，上限为 {2}。", "{0} : les EV totalisent {1}. Le maximum est {2}."),
        ["Selecciona una naturaleza válida."] = ("Select a valid nature.", "请选择有效的性格。", "Sélectionnez une nature valide."),
        ["La amistad debe estar entre 0 y 255."] = ("Friendship must be between 0 and 255.", "亲密度必须在 0 到 255 之间。", "L’amitié doit être entre 0 et 255."),
        ["Ese objeto no se puede equipar en este Pokémon."] = ("That item can’t be equipped on this Pokémon.", "这只宝可梦无法携带该道具。", "Cet objet ne peut pas être équipé sur ce Pokémon."),
        ["Esa habilidad no está disponible para este Pokémon."] = ("That ability isn’t available for this Pokémon.", "这只宝可梦无法使用该特性。", "Ce talent n’est pas disponible pour ce Pokémon."),
        ["{0} debe conservar al menos un movimiento."] = ("{0} must keep at least one move.", "{0} 至少要保留一个招式。", "{0} doit conserver au moins une capacité."),
        ["Coloca los movimientos en orden, sin espacios vacíos entre ellos."] = ("Put the moves in order, with no gaps between them.", "请按顺序排列招式，中间不要留空。", "Placez les capacités dans l’ordre, sans case vide entre elles."),
        ["No se puede repetir un movimiento."] = ("A move can’t be repeated.", "招式不能重复。", "Une capacité ne peut pas être répétée."),
        ["Hay un movimiento incompatible con este Pokémon."] = ("One of the moves isn’t compatible with this Pokémon.", "有招式与这只宝可梦不兼容。", "Une capacité est incompatible avec ce Pokémon."),

        // Opening a save
        ["Selecciona el archivo de guardado de una partida de Pokémon."] = ("Select the save file of a Pokémon game.", "请选择宝可梦游戏的存档文件。", "Sélectionnez le fichier de sauvegarde d’une partie Pokémon."),
        ["No reconozco ese archivo como una partida de Pokémon. Debe ser el guardado del juego (.sav, .srm, .dsv, main…), no un estado guardado del emulador."] = ("That file isn’t a Pokémon save. It must be the game’s own save (.sav, .srm, .dsv, main…), not an emulator save state.", "无法识别该文件为宝可梦存档。必须是游戏本身的存档（.sav、.srm、.dsv、main…），而不是模拟器的即时存档。", "Ce fichier n’est pas une partie Pokémon. Ce doit être la sauvegarde du jeu (.sav, .srm, .dsv, main…), pas une sauvegarde d’état de l’émulateur."),
        ["El archivo no tiene una firma de partida válida."] = ("The file doesn’t have a valid save signature.", "该文件没有有效的存档签名。", "Le fichier n’a pas de signature de partie valide."),
        ["La partida contiene un Pokémon con datos dañados."] = ("The save contains a Pokémon with damaged data.", "存档中有数据损坏的宝可梦。", "La partie contient un Pokémon aux données endommagées."),
        ["No se pudo consultar la tabla de evoluciones."] = ("The evolution table couldn’t be read.", "无法读取进化表。", "La table des évolutions n’a pas pu être lue."),

        // Bag rules
        ["Selecciona un Pokémon de esta partida."] = ("Select a Pokémon from this save.", "请选择此存档中的宝可梦。", "Sélectionnez un Pokémon de cette partie."),
        ["Ese objeto no se puede equipar en esta partida."] = ("That item can’t be equipped in this save.", "此存档中无法携带该道具。", "Cet objet ne peut pas être équipé dans cette partie."),
        ["{0} ya está equipado en {1}. Retíralo primero."] = ("{0} is already equipped on {1}. Remove it first.", "{1} 已携带 {0}。请先取下。", "{0} est déjà équipé sur {1}. Retirez-le d’abord."),
        ["No tienes unidades de ese objeto en la bolsa. Agrégalo en «Dinero y objetos»."] = ("You have none of that item in the bag. Add it in “Money and items”.", "背包中没有该道具。请在“金钱和道具”中添加。", "Vous n’avez pas cet objet dans le sac. Ajoutez-le dans « Argent et objets »."),
        ["Ese objeto no está disponible para esta partida."] = ("That item isn’t available for this save.", "此存档无法使用该道具。", "Cet objet n’est pas disponible pour cette partie."),
        ["{0}: la cantidad debe estar entre 0 y {1}."] = ("{0}: the quantity must be between 0 and {1}.", "{0}：数量必须在 0 到 {1} 之间。", "{0} : la quantité doit être entre 0 et {1}."),
        ["Este objeto está equipado. Retíralo desde «Estadísticas» antes de cambiar su cantidad."] = ("This item is equipped. Remove it from “Stats” before changing its quantity.", "此道具正在被携带。更改数量前请先在“能力”中取下。", "Cet objet est équipé. Retirez-le depuis « Statistiques » avant de changer sa quantité."),
        ["Solo puedes tener una unidad de ese objeto único."] = ("You can only have one of that unique item.", "该唯一道具只能拥有一个。", "Vous ne pouvez avoir qu’une unité de cet objet unique."),
        ["Selecciona un objeto."] = ("Select an item.", "请选择道具。", "Sélectionnez un objet."),
        ["La cantidad que agregas no puede ser negativa."] = ("The quantity you add can’t be negative.", "添加的数量不能为负数。", "La quantité ajoutée ne peut pas être négative."),
        ["Retira los objetos que acabas de equipar antes de deshacer la bolsa."] = ("Remove the items you just equipped before undoing the bag.", "撤销背包前，请先取下刚携带的道具。", "Retirez les objets que vous venez d’équiper avant d’annuler le sac."),
        ["No hay suficientes unidades de {0} para los Pokémon que lo llevan equipado."] = ("There isn’t enough {0} for the Pokémon holding it.", "{0} 的数量不足以供携带它的宝可梦使用。", "Il n’y a pas assez de {0} pour les Pokémon qui le tiennent."),
        ["No hay espacio para devolver {0} a la bolsa. Reduce su cantidad antes de retirarlo."] = ("There’s no room to return {0} to the bag. Lower its quantity before removing it.", "背包没有空间放回 {0}。取下前请先减少其数量。", "Pas de place pour remettre {0} dans le sac. Réduisez sa quantité avant de le retirer."),
        ["{0} solo se puede equipar en un Pokémon a la vez."] = ("{0} can only be equipped on one Pokémon at a time.", "{0} 同时只能由一只宝可梦携带。", "{0} ne peut être équipé que sur un Pokémon à la fois."),
        ["La bolsa debe conservar una unidad de {0}."] = ("The bag must keep one {0}.", "背包中必须保留一个 {0}。", "Le sac doit conserver une unité de {0}."),
        ["Solo puedes tener una unidad de {0}."] = ("You can only have one {0}.", "{0} 只能拥有一个。", "Vous ne pouvez avoir qu’une unité de {0}."),
        ["El bolsillo {0} solo tiene {1} espacios. Retira otro objeto primero."] = ("The {0} pocket only has {1} slots. Remove another item first.", "“{0}”口袋只有 {1} 格。请先移除其他道具。", "La poche {0} n’a que {1} emplacements. Retirez d’abord un autre objet."),
        ["El dinero debe estar entre 0 y {0:N0}."] = ("Money must be between 0 and {0:N0}.", "金钱必须在 0 到 {0:N0} 之间。", "L’argent doit être entre 0 et {0:N0}."),
        ["Un Pokémon tiene preparado un objeto que no está disponible en esta partida."] = ("A Pokémon has an item prepared that isn’t available in this save.", "有宝可梦准备携带此存档中不可用的道具。", "Un Pokémon a un objet préparé qui n’est pas disponible dans cette partie."),

        // Saving
        ["No se pudo volver a abrir la partida editada."] = ("The edited save couldn’t be reopened.", "无法重新打开编辑后的存档。", "La partie modifiée n’a pas pu être rouverte."),
        ["Cambió el tamaño de la partida."] = ("The size of the save changed.", "存档大小发生了变化。", "La taille de la partie a changé."),
        ["Cambió la estructura de la partida."] = ("The structure of the save changed.", "存档结构发生了变化。", "La structure de la partie a changé."),
        ["El dinero guardado no coincide con el solicitado."] = ("The money saved doesn’t match what was requested.", "保存的金钱与要求的不一致。", "L’argent enregistré ne correspond pas à celui demandé."),
        ["No se pudo comprobar {0} después de guardar."] = ("{0} couldn’t be verified after saving.", "保存后无法验证 {0}。", "{0} n’a pas pu être vérifié après l’enregistrement."),
        ["No hay espacio para {0} en la bolsa."] = ("There’s no room for {0} in the bag.", "背包中没有空间放 {0}。", "Pas de place pour {0} dans le sac."),
        ["No se pudo verificar la integridad de la partida editada."] = ("The integrity of the edited save couldn’t be verified.", "无法验证编辑后存档的完整性。", "L’intégrité de la partie modifiée n’a pas pu être vérifiée."),
        ["Se detectó un cambio fuera de los datos que editaste."] = ("A change was detected outside the data you edited.", "检测到你未编辑的数据发生了变化。", "Un changement a été détecté en dehors des données modifiées."),
        ["Se modificó un objeto que no editaste."] = ("An item you didn’t edit was modified.", "你未编辑的道具被修改了。", "Un objet que vous n’avez pas modifié a changé."),
        ["No se pudo verificar la cantidad o los datos de un objeto."] = ("An item’s quantity or data couldn’t be verified.", "无法验证道具的数量或数据。", "La quantité ou les données d’un objet n’ont pas pu être vérifiées."),
        ["No se pudo verificar la asignación de una megapiedra."] = ("A Mega Stone’s assignment couldn’t be verified.", "无法验证超级石的分配。", "L’attribution d’une Méga-Gemme n’a pas pu être vérifiée."),
        ["Se modificó un espacio vacío de las cajas."] = ("An empty box slot was modified.", "盒子的空位被修改了。", "Un emplacement vide des boîtes a été modifié."),
        ["Cierra {0} antes de guardar. Después vuelve a intentarlo."] = ("Close {0} before saving, then try again.", "保存前请关闭 {0}，然后重试。", "Fermez {0} avant d’enregistrer, puis réessayez."),
        ["La partida cambió fuera de la app. Ábrela de nuevo para cargar el progreso más reciente."] = ("The save changed outside the app. Open it again to load the latest progress.", "存档在本应用之外发生了变化。请重新打开以载入最新进度。", "La partie a changé en dehors de l’application. Rouvrez-la pour charger la progression la plus récente."),
        ["No se pudo verificar el respaldo."] = ("The backup couldn’t be verified.", "无法验证备份。", "La copie n’a pas pu être vérifiée."),
        ["La partida o el emulador cambió mientras se guardaba. No se reemplazó el archivo."] = ("The save or the emulator changed while saving. The file wasn’t replaced.", "保存期间存档或模拟器发生了变化。文件未被替换。", "La partie ou l’émulateur a changé pendant l’enregistrement. Le fichier n’a pas été remplacé."),
        ["El archivo de destino cambió mientras se guardaba. No se reemplazó."] = ("The destination file changed while saving. It wasn’t replaced.", "保存期间目标文件发生了变化，未被替换。", "Le fichier de destination a changé pendant l’enregistrement. Il n’a pas été remplacé."),
        ["La verificación final no coincide. Conserva el respaldo."] = ("The final check doesn’t match. Keep the backup.", "最终验证不一致。请保留备份。", "La vérification finale ne correspond pas. Conservez la copie."),

