        ["Cambiar el nombre o los ID hace que el juego trate a tus Pokémon actuales como recibidos de otro entrenador."] = ("Changing the name or the IDs makes the game treat your current Pokémon as received from another trainer.", "更改名字或编号后，游戏会把你现有的宝可梦视为从其他训练家那里得到的。", "Changer le nom ou les ID fait que le jeu traite vos Pokémon actuels comme reçus d’un autre dresseur."),
        ["En este juego la ropa y el modelo se guardan aparte: cambiar el género no los ajusta. Si la partida da problemas, recupera el respaldo automático."] = ("This game keeps clothes and the character model separately, so changing the gender doesn't adjust them. If the game misbehaves, restore the automatic backup.", "此游戏单独保存服装和人物模型，更改性别不会调整它们。如果存档出现问题，请恢复自动备份。", "Ce jeu enregistre les vêtements et le modèle à part : changer le genre ne les ajuste pas. En cas de problème, restaurez la sauvegarde automatique."),
        ["Selecciona un género válido."] = ("Select a valid gender.", "请选择有效的性别。", "Sélectionnez un genre valide."),
        ["El ID de entrenador debe estar entre 0 y {0}."] = ("The trainer ID must be between 0 and {0}.", "训练家编号必须在 0 到 {0} 之间。", "L’ID Dresseur doit être compris entre 0 et {0}."),
        ["El ID secreto debe estar entre 0 y {0}."] = ("The secret ID must be between 0 and {0}.", "隐藏编号必须在 0 到 {0} 之间。", "L’ID secret doit être compris entre 0 et {0}."),
        ["Esa combinación de ID no cabe en este juego."] = ("That ID combination doesn't fit in this game.", "此游戏无法保存该编号组合。", "Cette combinaison d’ID ne tient pas dans ce jeu."),
        ["El tiempo de juego llega hasta {0} horas, con minutos y segundos entre 0 y 59."] = ("Play time goes up to {0} hours, with minutes and seconds between 0 and 59.", "游戏时间最多 {0} 小时，分钟和秒必须在 0 到 59 之间。", "Le temps de jeu va jusqu’à {0} heures, avec des minutes et des secondes entre 0 et 59."),
        ["Las medallas no coinciden con este juego."] = ("Those badges don't match this game.", "这些徽章与此游戏不符。", "Ces badges ne correspondent pas à ce jeu."),
        ["No se pudieron comprobar los datos del entrenador después de guardar."] = ("The trainer data couldn't be verified after saving.", "保存后无法验证训练家数据。", "Impossible de vérifier les données du dresseur après l’enregistrement."),
        ["Esta partida no guarda un entrenador que se pueda editar aquí."] = ("This save has no trainer that can be edited here.", "此存档没有可在此编辑的训练家数据。", "Cette partie n’a pas de dresseur modifiable ici."),
